import {openSDKRelay,requestSDKRelay,closeSDKRelay} from './pico-sdk-relay.js';
import {boardKey} from './board-hardware.js';
import {projectFiles,sourceKey} from './source-files.js';
import {encodeBytes} from './unified-project.js';
import {nativeSDKImage} from './pico-sdk-image.js';
const KEY='wirevo-sdk-connection-v1';let current;
export function validateSDKConnection(raw){if(!raw||raw.protocol!==1)throw Error('Bu dosya SDK bağlantı dosyası değil. Yardımcının connection.json dosyasını seçin.');if(!Number.isInteger(raw.port)||raw.port<1||raw.port>65535)throw Error('SDK portu geçersiz. Güncel bağlantı dosyasını seçin.');if(typeof raw.token!=='string'||!raw.token.trim())throw Error('Bağlantı kodu eksik. Önce yardımcının connection.json dosyasını seçin.');if(!/^[A-Za-z0-9_-]{32,100}$/.test(raw.token))throw Error('SDK bağlantı kodu geçersiz. Güncel bağlantı dosyasını yeniden seçin.');return {protocol:1,port:raw.port,token:raw.token,...(raw.transport==='window'?{transport:'window'}:{})};}
export function getSDKConnection(){if(current)return current;try{const text=globalThis.sessionStorage?.getItem(KEY);return text?(current=validateSDKConnection(JSON.parse(text))):null;}catch{return null;}}
export function disconnectSDK(){closeSDKRelay();current=null;try{globalThis.sessionStorage?.removeItem(KEY);}catch{}}
function connectionFailure(browser,timeout=false){return Error((timeout?'SDK bağlantısı zaman aşımına uğradı. ':'SDK yardımcısına ulaşılamadı. ')+'Yardımcının açık olduğunu kontrol edin. '+(browser?.brave?'Brave: Wirevo site ayarlarında Yerel ağ / Localhost erişimini yalnız bu site için İzin ver yapın, sayfayı yenileyip Doğrudan bağlan düğmesine basın.':'Tarayıcının Wirevo için yerel ağ erişim iznini kontrol edin.'));}
async function request(connection,path,{fetcher=fetch,signal,method='GET',body,browser=globalThis.navigator}={}){if(signal?.aborted)throw new DOMException('İptal edildi.','AbortError');if(connection.transport==='window')return requestSDKRelay(connection,path,{method,body,signal});let response;try{response=await fetcher('http://127.0.0.1:'+connection.port+path,{method,mode:'cors',credentials:'omit',cache:'no-store',headers:{Authorization:'Bearer '+connection.token,...(body!==undefined?{'Content-Type':'application/json'}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{}),signal});}catch(e){if(e.name==='AbortError')throw e;throw connectionFailure(browser);}const data=await response.json();if(!response.ok)throw Error(data.error||'SDK yardımcısı HTTP '+response.status);return data;}
export async function connectSDK(raw,{fetcher=fetch,timeoutMs=20000,browser=globalThis.navigator}={}){const c=validateSDKConnection(raw);delete c.transport;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),timeoutMs);try{const status=await request(c,'/v1/status',{fetcher,signal:controller.signal,browser});if(status.protocol!==1||status.engine!=='official-pico-sdk')throw Error('SDK yardımcısının sürümü uyumlu değil.');closeSDKRelay();current=c;try{globalThis.sessionStorage?.setItem(KEY,JSON.stringify(c));}catch{}return status;}catch(error){if(controller.signal.aborted)throw connectionFailure(browser,true);throw error;}finally{clearTimeout(timeout);}}
function pause(ms,signal){return new Promise((resolve,reject)=>{const abort=()=>{clearTimeout(t);reject(new DOMException('İptal edildi.','AbortError'));},t=setTimeout(()=>{signal?.removeEventListener('abort',abort);resolve();},ms);if(signal?.aborted)return abort();signal?.addEventListener('abort',abort,{once:true});});}
export async function compileLocalPicoSDK(project,{onProgress=()=>{},signal,connection=getSDKConnection(),fetcher=fetch,pollMs=200}={}){
 if(!connection)throw Error('Önce Pico SDK / CMake panelinden bilgisayarınızdaki SDK yardımcısına bağlanın.');
 connection=validateSDKConnection(connection);if(project.language!=='c'||project.settings?.picoArchitecture==='riscv')throw Error('Yerel SDK bağlantısı Pico C / ARM projesi gerektirir.');
 const id=crypto.randomUUID(),key=sourceKey(project),board=boardKey(project),files=projectFiles(project),controller=new AbortController();let cursor=0,ended=false,jobError='';
 const cancel=()=>{controller.abort();request(connection,'/v1/jobs/'+id+'/cancel',{fetcher,method:'POST',body:{}}).catch(()=>{});};
 signal?.addEventListener('abort',cancel,{once:true});const timer=setTimeout(cancel,310000);
 try{if(signal?.aborted)throw new DOMException('İptal edildi.','AbortError');onProgress('Resmi Pico SDK / CMake · bu bilgisayarda derleniyor');
  const started=await request(connection,'/v1/jobs',{fetcher,signal:controller.signal,method:'POST',body:{id,sourceKey:key,target:project.settings?.picoSDKTarget||'',project:{board,architecture:'arm',language:'c',code:project.code,files:files.filter(f=>f.name!=='main.c')}}});if(started.id!==id)throw Error('SDK derleme kimliği eşleşmiyor.');
  for(;;){const d=await request(connection,'/v1/jobs/'+id+'?cursor='+cursor,{fetcher,signal:controller.signal});if(d.id!==id||d.board!==board||d.sourceKey!==key||!Number.isSafeInteger(d.cursor))throw Error('SDK yanıtı kaynak/kart ile eşleşmiyor.');cursor=d.cursor;if(d.log){jobError=(jobError+d.log).slice(-200000);onProgress(d.log.trimEnd());}
   if(d.state==='succeeded'){ended=true;const f=d.result;if(!f||typeof f.uf2!=='string'||f.uf2.length>1400000)throw Error('SDK firmware verisi geçersiz.');const uf2=Uint8Array.from(atob(f.uf2),c=>c.charCodeAt(0));if(uf2.length!==f.bytes)throw Error('SDK firmware boyutu eşleşmiyor.');const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',uf2)),b=>b.toString(16).padStart(2,'0')).join('');if(hash!==f.sha256)throw Error('SDK firmware SHA-256 eşleşmiyor.');const image=nativeSDKImage(uf2,board);if(image.length>600000)throw Error('SDK firmware proje aktarım sınırını aşıyor.');return {format:'pico-sdk-bin',payload:encodeBytes(image),flashBytes:image.length,staticRamBytes:0,stderr:[],sdkTarget:f.target};}
   if(d.state==='failed'){ended=true;throw Error(jobError||'Resmi SDK derlemesi başarısız.');}if(d.state==='cancelled'){ended=true;throw new DOMException('İptal edildi.','AbortError');}if(!['queued','building'].includes(d.state))throw Error('SDK derleme durumu geçersiz.');await pause(pollMs,controller.signal);
  }
 }finally{clearTimeout(timer);signal?.removeEventListener('abort',cancel);if(!ended)cancel();}
}

export async function connectSDKWindow(raw,options={}){const c={...validateSDKConnection(raw),transport:'window'};const status=await openSDKRelay(c,options);current=c;try{globalThis.sessionStorage?.setItem(KEY,JSON.stringify(c));}catch{}return status;}
